CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '', company text NOT NULL DEFAULT '');
GRANT SELECT, INSERT, UPDATE ON public.profiles TO authenticated;
GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY profiles_read ON public.profiles FOR SELECT TO authenticated USING (id = auth.uid());
CREATE POLICY profiles_insert ON public.profiles FOR INSERT TO authenticated WITH CHECK (id = auth.uid());
CREATE POLICY profiles_update ON public.profiles FOR UPDATE TO authenticated USING (id = auth.uid()) WITH CHECK (id = auth.uid());
CREATE FUNCTION public.create_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN INSERT INTO public.profiles(id, display_name, company) VALUES (new.id, coalesce(new.raw_user_meta_data->>'display_name', ''), coalesce(new.raw_user_meta_data->>'company', '')); RETURN new; END; $$;
CREATE TRIGGER create_profile_on_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_profile();
CREATE TABLE public.visualization_projects (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL DEFAULT auth.uid(), name text NOT NULL DEFAULT 'Untitled room', room_path text NOT NULL, reference_path text NOT NULL, settings jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.visualization_projects TO authenticated;
GRANT ALL ON public.visualization_projects TO service_role;
ALTER TABLE public.visualization_projects ENABLE ROW LEVEL SECURITY;
CREATE POLICY projects_owner ON public.visualization_projects FOR ALL TO authenticated USING (user_id = auth.uid()) WITH CHECK (user_id = auth.uid());
CREATE TABLE public.visualization_images (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL REFERENCES public.visualization_projects(id) ON DELETE CASCADE, user_id uuid NOT NULL DEFAULT auth.uid(), image_path text NOT NULL, instruction text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.visualization_images TO authenticated;
GRANT ALL ON public.visualization_images TO service_role;
ALTER TABLE public.visualization_images ENABLE ROW LEVEL SECURITY;
CREATE POLICY images_owner ON public.visualization_images FOR ALL TO authenticated USING (user_id = auth.uid() AND EXISTS (SELECT 1 FROM public.visualization_projects p WHERE p.id = project_id AND p.user_id = auth.uid())) WITH CHECK (user_id = auth.uid() AND EXISTS (SELECT 1 FROM public.visualization_projects p WHERE p.id = project_id AND p.user_id = auth.uid()));
CREATE INDEX visualization_projects_owner_idx ON public.visualization_projects(user_id, updated_at DESC);
CREATE INDEX visualization_images_project_idx ON public.visualization_images(project_id, created_at DESC);
CREATE TABLE public.image_access_blocks (user_id uuid PRIMARY KEY, reason text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.image_access_blocks TO authenticated;
GRANT ALL ON public.image_access_blocks TO service_role;
ALTER TABLE public.image_access_blocks ENABLE ROW LEVEL SECURITY;
CREATE POLICY access_block_read ON public.image_access_blocks FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE POLICY visualization_files_read ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'visualizations' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY visualization_files_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'visualizations' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY visualization_files_update ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'visualizations' AND (storage.foldername(name))[1] = auth.uid()::text) WITH CHECK (bucket_id = 'visualizations' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY visualization_files_delete ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'visualizations' AND (storage.foldername(name))[1] = auth.uid()::text);